{
  "findings": [
    {
      "check_id": "CKV_AZURE_27",
      "title": "MSSQL security alerts are not sent to account administrators",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "The policy does not enable email notifications for subscription service and co-administrators, which could delay awareness of database security threats."
    },
    {
      "check_id": "CKV_AZURE_25",
      "title": "MSSQL threat detection types are not all enabled",
      "resource": "azurerm_mssql_server_security_alert_policy.alertpolicy6",
      "severity": "MEDIUM",
      "explanation": "The policy explicitly disables SQL injection and data exfiltration alerts, leaving significant database attack and exfiltration activity undetected."
    }
  ],
  "patched_code": "resource \"azurerm_mssql_server_security_alert_policy\" \"alertpolicy6\" {\n  resource_group_name        = azurerm_resource_group.example.name\n  server_name                = azurerm_mssql_server.mssql6.name\n  state                      = \"Enabled\"\n  storage_endpoint           = azurerm_storage_account.security_storage_account.primary_blob_endpoint\n  storage_account_access_key = azurerm_storage_account.security_storage_account.primary_access_key\n  disabled_alerts            = []\n  retention_days             = 20\n  email_account_admins       = true\n  email_addresses            = [\"securityengineer@bridgecrew.io\"]\n}\n",
  "fix_summary": "Enabled security alert emails for account administrators and removed the exclusions for SQL injection and data exfiltration so all threat detection types remain active."
}
